/**
 * Renders a `content/index.ts` that imports every bank JSON file of a subject and exports
 * them as `bankQuestions`. Regenerated by the subject's content scripts whenever a file is saved.
 */
export function renderContentIndex(files: readonly string[]): string {
  const ident = (f: string) =>
    f
      .replace(/\.json$/, '')
      .replace(/-([a-z0-9])/g, (_, c: string) => c.toUpperCase())
      .replace(/^([0-9])/, '_$1');
  const imports = files.map((f) => `import ${ident(f)} from './${f}';`).join('\n');
  const list = files.map((f) => `  ${ident(f)},`).join('\n');
  return `// GENERATO dagli script content:* (saveApproved): un import per ogni JSON in questa cartella.
import type { BankFile, BankQuestion } from '@lg/core';
${imports}

const files = [
${list}
] as unknown as BankFile[];

export const bankQuestions: BankQuestion[] = files.flatMap((f) => f.questions);
`;
}
